-- Dedicated synthetic staging identities only. Evidence and contract fixtures
-- exist inside this transaction and are rolled back after all assertions.
begin;
do $test$
declare
  admin_user auth.users%rowtype;
  task_contract text; assessment_id text; created_submissions text[]:=array[]::text[];
  staff auth.users%rowtype;
  sponsor auth.users%rowtype;
  c public.pilot_cohorts%rowtype;
  person record;
  version_id text;
  fixture_registry_id text := gen_random_uuid()::text;
  fixture_contract_id text := 'QA-REVIEWED-'||gen_random_uuid()::text;
  field_id text := 'QA.REVIEWED.'||gen_random_uuid()::text;
  family text := 'QF-QA'||replace(gen_random_uuid()::text,'-','');
  evidence_id text;
  submission_id text;
  first_user text;
  first_evidence text;
  first_submission text;
  result jsonb;
  first_mapping text;
  mapping_ids text[];
  rubric_id text := gen_random_uuid()::text;
  denied boolean;
begin
  select * into strict admin_user from auth.users where email='fullscope-20261006-admin@bis-staging.example.invalid';
  select * into strict staff from auth.users where email='fullscope-20261006-facilitator@bis-staging.example.invalid';
  select * into strict sponsor from auth.users where email='fullscope-20261006-sponsor@bis-staging.example.invalid';
  select * into strict c from public.pilot_cohorts where name='BIS hardening synthetic cohort 20261006' and status='ACTIVE';
  select id into strict version_id from public.content_library_versions order by created_at limit 1;
  insert into public.question_evidence_contracts(id,lab_code,question_family,competency_id,evidence_class,stage_ceiling,source_nature,aggregation_policy,model_review_policy,claim_authority,contract_status,measurement_status,privacy_scope,allowed_inference,forbidden_inference,source_reference,source_hash)
  values(fixture_contract_id,c.lab_code,family,'AC-C04','LEARNING_CHECK','EXPLAIN','SELF_REPORT','EXCLUDE','FACILITATOR_SHARED_ONLY','HUMAN_REVIEW_REQUIRED','APPROVED_MEANING','NOT_VALIDATED','PRIVATE_BY_DEFAULT','Synthetic task review only','No attained stage or transfer claim','QA-only rollback fixture',repeat('0',64));
  insert into public.question_analysis_registry(id,version_id,lab_code,lab_version,semantic_field_id,question_family,label,evidence_class,answer_model,sensitivity,aggregate_policy,status)
  values(fixture_registry_id,version_id,c.lab_code,c.lab_version,field_id,family,'Synthetic question','INTERPRETATION','TEXT','P2','EXCLUDE','CANDIDATE');
  select array_agg(id) into mapping_ids from public.curriculum_evidence_mappings where registry_id=fixture_registry_id;
  -- Require source-governed mapping to have been generated by the real triggers.
  select m.id into strict first_mapping from public.curriculum_evidence_mappings m where m.registry_id=fixture_registry_id and m.classification_status='APPROVED' order by m.created_at desc limit 1;
  insert into public.assessment_rubric_versions(id,lab_code,lab_version,title,task_id,source_reference,semantic_field_ids,mapping_ids,criteria,scale_min,scale_max,created_by)
  values(rubric_id,c.lab_code,c.lab_version,'Synthetic learning review',field_id,'QA-only rollback fixture',array[field_id],array[first_mapping],'[{"id":"QA","label":"Synthetic criterion"}]',0,5,staff.id::text);
  perform set_config('request.jwt.claims',jsonb_build_object('sub',admin_user.id,'role','authenticated','email',admin_user.email)::text,true);
  execute 'set local role authenticated';
  task_contract=public.bis_publish_development_contract(jsonb_build_object('labCode',c.lab_code,'labVersion',c.lab_version,'competencyId','AC-C04','mappingIds',jsonb_build_array(first_mapping),'title','Synthetic explanation criteria','source','QA-only rollback fixture','sourceHash',repeat('0',64),'ceiling','EXPLAIN','comparisonKey',family,'sourceNature','SELF_REPORT','followUpDays',null,'perceptionField',null));
  execute 'reset role';
  for person in select m.learner_user_id,le.id as enrolment_id from public.cohort_members m join public.lab_enrollments le on le.user_id=m.learner_user_id and le.lab_code=c.lab_code and le.lab_version=c.lab_version and le.status<>'WITHDRAWN' join auth.users u on u.id::text=m.learner_user_id where m.cohort_id=c.id and m.status='ACTIVE' and u.email like 'fullscope-20261006-%@bis-staging.example.invalid' order by m.learner_user_id limit 3 loop
    evidence_id=gen_random_uuid()::text;submission_id=gen_random_uuid()::text;
    if first_user is null then first_user=person.learner_user_id;first_evidence=evidence_id;first_submission=submission_id;end if;
    insert into public.evidence_records(id,user_id,lab_code,lab_version,investigation_id,semantic_field_id,source_object_type,source_object_id,provenance,value_type,value,sensitivity,occurred_at,enrolment_id)
    values(evidence_id,person.learner_user_id,c.lab_code,c.lab_version,'QA.REVIEWED',field_id,'RESPONSE',evidence_id,'LR','TEXT','QA-PRIVATE-REVIEWED-WORDING','P2',now(),person.enrolment_id);
    insert into public.evidence_submissions(id,user_id,cohort_id,evidence_ids,title,request_key) values(submission_id,person.learner_user_id,c.id,array[evidence_id],'Synthetic shared task',submission_id);
    insert into public.evidence_assessments(submission_id,rubric_version_id,assessor_id,assessor_email,disposition,feedback,criterion_scores,request_key)
    values(submission_id,rubric_id,staff.id::text,staff.email,'REVIEWED','Synthetic review','[{"criterionId":"QA","score":5,"rationale":"Synthetic"}]',gen_random_uuid()::text) returning id into assessment_id;
    created_submissions=array_append(created_submissions,submission_id);
    perform set_config('request.jwt.claims',jsonb_build_object('sub',staff.id,'role','authenticated','email',staff.email)::text,true);execute 'set local role authenticated';
    perform public.bis_record_development_review(jsonb_build_object('assessmentId',assessment_id,'contractId',task_contract,'stage','EXPLAIN','criteria',jsonb_build_object('explains',true),'context','SCHOOL','independent',false,'requestKey',assessment_id));
    execute 'reset role';
  end loop;
  if first_user is null then raise exception 'Prepared eligible synthetic learners required';end if;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',staff.id,'role','authenticated','email',staff.email)::text,true);
  execute 'set local role authenticated';
  result=public.bis_development_learner_report(first_user,c.id);
  if not exists(select 1 from jsonb_array_elements(result) r where r->>'authorityId'=task_contract and r->>'stage'='EXPLAIN') then raise exception 'Reviewed development stage unavailable';end if;
  if result::text like '%QA-PRIVATE-REVIEWED-WORDING%' then raise exception 'Private wording reached development report';end if;
  result=public.bis_development_programme_report(c.id);
  if result->'competencies'<>'[]'::jsonb then raise exception 'Outcome sharing was not separately permitted';end if;
  denied=false;begin perform public.bis_development_reporting_permission(first_submission,true);exception when insufficient_privilege then denied=true;end;
  if not denied then raise exception 'Facilitator granted learner permission';end if;
  execute 'reset role';
  for person in select s.id,s.user_id,u.email from public.evidence_submissions s join auth.users u on u.id::text=s.user_id where s.id=any(created_submissions) loop
    perform set_config('request.jwt.claims',jsonb_build_object('sub',person.user_id,'role','authenticated','email',person.email)::text,true);
    execute 'set local role authenticated';perform public.bis_development_reporting_permission(person.id,true);execute 'reset role';
  end loop;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',staff.id,'role','authenticated','email',staff.email)::text,true);execute 'set local role authenticated';
  result=public.bis_development_programme_report(c.id);
  if not exists(select 1 from jsonb_array_elements(result->'competencies') r where r->>'competencyId'='AC-C04' and exists(select 1 from jsonb_array_elements(r->'distribution') x where x->>'code'='EXPLAIN' and (x->>'count')::int=3)) then raise exception 'Permitted stage distribution missing';end if;
  if result::text like '%'||first_user||'%' or result::text like '%QA-PRIVATE-REVIEWED-WORDING%' then raise exception 'Individual detail reached aggregate';end if;
  execute 'reset role';
  update public.evidence_submissions set revoked_at=now() where id=first_submission;
  execute 'set local role authenticated';
  if public.bis_development_learner_report(first_user,c.id)<>'[]'::jsonb then raise exception 'Revoked evidence still reported';end if;
  if public.bis_development_programme_report(c.id)->'competencies'<>'[]'::jsonb then raise exception 'Small remaining cell not suppressed';end if;
  execute 'reset role';
  update public.question_evidence_contracts set contract_status='RETIRED' where id=fixture_contract_id;
  execute 'set local role authenticated';
  if exists(select 1 from jsonb_array_elements(public.bis_development_contract_workspace(c.id)->'contracts') x where x->>'id'=task_contract) then raise exception 'Retired assessment authority remains selectable';end if;
  execute 'reset role';
  perform set_config('request.jwt.claims',jsonb_build_object('sub',sponsor.id,'role','authenticated','email',sponsor.email)::text,true);execute 'set local role authenticated';
  denied=false;begin perform public.bis_development_learner_report(first_user,c.id);exception when insufficient_privilege then denied=true;end;
  if not denied then raise exception 'Sponsor accessed individual development';end if;
  execute 'reset role';
end $test$;
rollback;
select 'PASS: authored criteria publication, human stage review, learner permission and revocation, privacy-safe stage distribution, retired source invalidation and sponsor denial; fixtures rolled back' as verification;
